1. 把第 23 章的 Student 拆成 student.h / student.c / main.c 三个文件，编译运行。
2. 写一个 math 模块（add/sub/mul/div），头文件声明，.c 实现，main 调用。
3. 写一个 Makefile 自动编译上述多文件项目。

## 引入：把数据"串"起来

数组大小固定、插入删除慢（要移动后面所有元素）。链表用指针把分散的节点串起来，能动态增长、O(1) 插入删除。栈和队列是两种特殊的"受限"结构——栈后进先出，队列先进先出。这是数据结构入门的三大基础。

### 39.1 单链表

链表节点：数据 + 指向下一节点的指针。

```c
typedef struct Node {
    int data;
    struct Node *next;
} Node;
```

**生活类比**：寻宝游戏，每张纸条写着"宝藏线索 + 下一张纸条的位置"。

### 39.2 创建节点

```c
#include <stdlib.h>

Node *create_node(int data) {
    Node *n = malloc(sizeof(Node));
    if (n) {
        n->data = data;
        n->next = NULL;
    }
    return n;
}
```

### 39.3 头插法

```c
typedef struct { Node *head; } List;

void push_front(List *l, int data) {
    Node *n = create_node(data);
    if (!n) return;
    n->next = l->head;
    l->head = n;
}
```

新节点插到链表头部，原来头部变成第二个。

### 39.4 遍历

```c
void print_list(const List *l) {
    for (Node *p = l->head; p; p = p->next) {
        printf("%d -> ", p->data);
    }
    printf("NULL\n");
}
```

### 39.5 释放整个链表

```c
void free_list(List *l) {
    Node *p = l->head;
    while (p) {
        Node *next = p->next;
        free(p);
        p = next;
    }
    l->head = NULL;
}
```

每个节点都要 free。注意先保存 next 再 free 当前——否则 free 后就读不到 next 了。

### 39.6 完整链表示例

```c
#include <stdio.h>
#include <stdlib.h>

typedef struct Node { int data; struct Node *next; } Node;
typedef struct { Node *head; } List;

void push_front(List *l, int data) {
    Node *n = malloc(sizeof(Node));
    n->data = data; n->next = l->head; l->head = n;
}

void print_list(const List *l) {
    for (Node *p = l->head; p; p = p->next) printf("%d -> ", p->data);
    printf("NULL\n");
}

void free_list(List *l) {
    Node *p = l->head;
    while (p) { Node *nx = p->next; free(p); p = nx; }
    l->head = NULL;
}

int main(void) {
    List l = {NULL};
    push_front(&l, 3);
    push_front(&l, 2);
    push_front(&l, 1);
    print_list(&l);    // 1 -> 2 -> 3 -> NULL
    free_list(&l);
    return 0;
}
```

### 39.7 栈：后进先出（LIFO）

栈像一摞盘子——只能从顶上放、从顶上拿。最后放的先拿走。

```c
typedef struct { Node *top; } Stack;

void push(Stack *s, int data) {
    Node *n = malloc(sizeof(Node));
    n->data = data; n->next = s->top; s->top = n;
}

int pop(Stack *s) {
    if (!s->top) return -1;   // 空栈
    Node *n = s->top;
    int v = n->data;
    s->top = n->next;
    free(n);
    return v;
}

int is_empty(const Stack *s) { return s->top == NULL; }
```

**应用**：函数调用栈、撤销操作、表达式求值、括号匹配。

### 39.8 队列：先进先出（FIFO）

队列像排队买票——先来的先买到。需要头尾两个指针：

```c
typedef struct {
    Node *front, *rear;
} Queue;

void enqueue(Queue *q, int data) {
    Node *n = malloc(sizeof(Node));
    n->data = data; n->next = NULL;
    if (q->rear) q->rear->next = n;
    else q->front = n;       // 第一个元素
    q->rear = n;
}

int dequeue(Queue *q) {
    if (!q->front) return -1;
    Node *n = q->front;
    int v = n->data;
    q->front = n->next;
    if (!q->front) q->rear = NULL;   // 队空
    free(n);
    return v;
}
```

**应用**：任务调度、广度优先搜索、缓冲区。

### 39.9 综合：括号匹配（栈应用）

```c
#include <stdio.h>
#include <string.h>
#include <stdbool.h>

bool is_balanced(const char *s) {
    char stack[100];
    int top = -1;
    for (int i = 0; s[i]; i++) {
        char c = s[i];
        if (c == '(' || c == '[' || c == '{') {
            stack[++top] = c;
        } else if (c == ')') {
            if (top < 0 || stack[top--] != '(') return false;
        } else if (c == ']') {
            if (top < 0 || stack[top--] != '[') return false;
        } else if (c == '}') {
            if (top < 0 || stack[top--] != '{') return false;
        }
    }
    return top == -1;
}

int main(void) {
    printf("%d\n", is_balanced("({[]})"));    // 1
    printf("%d\n", is_balanced("([)]"));      // 0
    return 0;
}
```

### 39.10 时间复杂度对比

| 操作 | 数组 | 链表 | 栈 | 队列 |
|------|------|------|------|------|
| 访问 | O(1) | O(n) | O(1)（顶） | O(1)（头） |
| 插入头 | O(n) | O(1) | - | - |
| 插入尾 | O(1) 摊销 | O(1)（有尾指针） | - | - |
| 删除头 | O(n) | O(1) | O(1) | O(1) |

### 39.11 常见错误

1. **链表忘了 free**：内存泄漏。
2. **free 后访问 next**：先保存 next 再 free。
3. **空链表操作**：head 为 NULL 时访问 head->data 崩溃。
4. **栈/队列为空时 pop/dequeue**：要检查。
5. **链表尾部循环**：插入操作忘了把新节点 next 设 NULL，可能成环。

### 39.12 本节要点

- 链表节点 = 数据 + 指向下一节点的指针。
- 链表动态增长，O(1) 头插删，O(n) 随机访问。
- 栈 LIFO，push/pop 都在顶。
- 队列 FIFO，enqueue 尾、dequeue 头。
- 释放链表要遍历逐个 free，先存 next。

